import raw from "@/data/benchmarks.json";

/** Shape of apps/site/src/data/benchmarks.json, generated by scripts/benchmarks_site.py. */
export type Suite = {
  id: string;
  title: string;
  what: string;
  total: number;
  /** The engine computed the right answer. */
  correct: number;
  /** The engine refused for a stated reason, as it should. */
  refused: number;
  /** A wrong answer to the same request was rejected. */
  rejected: number;
  /** A known gap: reported, not hidden. */
  pending: number;
  sources: string[];
  command: string;
  doc: string;
};
export type Verification = {
  problems: number;
  correct: number;
  refused: number;
  false_accepts: number;
  false_rejects: number;
  counterexamples_found: number;
  pending: number;
  known_open: number;
  evidence: Record<string, number>;
  source: string;
  doc: string;
  command: string;
};
export type ChatModel = {
  alias: string;
  base_model: string | null;
  family: string | null;
  parameter_size: string | null;
  quantization: string | null;
  digest: string | null;
  thinking_requested: boolean;
  reply_limit: number | null;
  reply_limit_is_host_default: boolean;
};
export type ChatRow = {
  id: string;
  title: string;
  report: string;
  date: string;
  model: ChatModel;
  run: {
    runs: number;
    cases: number;
    repeats: number;
    seed: number;
    compute_limit_seconds: number;
    cases_digest: string;
    code: string;
  };
  passed: number;
  per_repeat: number[];
  measured: Record<string, number>;
  median_seconds: number;
  p95_seconds: number;
};
export type Target = { id: string; label: string; target: number; measured: number; met: boolean };
export type Benchmarks = {
  suites: Suite[];
  verification: Verification;
  chat: { rows: ChatRow[]; targets: Target[] };
};

export const BENCHMARKS = raw as Benchmarks;

export const pct = (value: number) => `${(100 * value).toFixed(1)}%`;

/**
 * The model as its host reported it, by what it is: the base model first, the alias it is served under last.
 * An alias can be re-pointed and says nothing about the weights.
 */
export function modelLine(m: ChatModel): string {
  const what = m.base_model ?? m.alias;
  const parts = [
    what,
    m.parameter_size,
    m.quantization,
    m.digest ? `digest ${m.digest}` : null,
    m.base_model && m.base_model !== m.alias ? `served as ${m.alias}` : null,
    m.thinking_requested ? "thinking on" : "thinking off",
    m.reply_limit
      ? `reply limit ${m.reply_limit} tokens${m.reply_limit_is_host_default ? " (the host's default)" : ""}`
      : null,
  ];
  return parts.filter(Boolean).join(" · ");
}
